import java.util.*;

public class TextEditing {
    public static int maxLength(String s) {
        int max = 0;
        int current = 0;
        boolean inside = false;
        for (int i = 0; i < s.length(); i++) {
            char ch = s.charAt(i);
            if (ch == '(') {
                inside = true;
            } else if (ch == ')') {
                inside = false;
                current = 0;
            } else if (!inside) {
                if (ch == '_') {
                    current = 0;
                } else {
                    current++;
                    if (current > max) {
                        max = current;
                    }
                }
            }
        }
        return max;
    }

    public static int words(String s) {
        int total = 0;
        int insideWords = 0;
        boolean inside = false;
        boolean inWord = false;
        for (int i = 0; i < s.length(); i++) {
            char ch = s.charAt(i);
            if (ch == '(') {
                inside = true;
            } else if (ch == ')') {
                total += insideWords;
                insideWords = 0;
                inWord = false;
                inside = false;
            } else if (inside) {
                if (ch == '_') {
                    inWord = false;
                } else {
                    if (!inWord) {
                        insideWords++;
                    }
                    inWord = true;
                }
            }
        }
        return total;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        String s = sc.next();
        System.out.println(maxLength(s) + " " + words(s));
    }
}
